lines = open(PATH, encoding="utf-8").read().split("\n")
out = []
for ln in lines:
    if ln.startswith("| Rule | Enforced by"):
        ln = ln.rstrip() + " Live audit (2026-11-22) |"
    elif ln.startswith("|---|---|---|---|"):
        ln = ln.rstrip() + "---|"
    else:
        m = re.match(r"\| (R\d+) \|", ln)
        if m and m.group(1) in CELLS:
            ln = ln.rstrip() + " " + CELLS[m.group(1)].replace("|", "/") + " Evidence folder: `" + D + "`. |"
    out.append(ln)
open(PATH, "w", encoding="utf-8").write("\n".join(out))
print("ok", sum(1 for l in out if l.startswith("| R")))
